#include <openssl/evp.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    EVP_CIPHER *cipher128;
    EVP_CIPHER *cipher192;
    EVP_CIPHER *cipher256;
    unsigned char *outbuf;
    size_t outcap;
} GcmState;

static EVP_CIPHER *pick(GcmState *s, int klen) {
    if (klen == 16) return s->cipher128;
    if (klen == 24) return s->cipher192;
    return s->cipher256;
}

GcmState *gcm_init(void) {
    GcmState *s = calloc(1, sizeof(*s));
    s->ctx = EVP_CIPHER_CTX_new();
    s->cipher128 = EVP_CIPHER_fetch(NULL, "AES-128-GCM", NULL);
    s->cipher192 = EVP_CIPHER_fetch(NULL, "AES-192-GCM", NULL);
    s->cipher256 = EVP_CIPHER_fetch(NULL, "AES-256-GCM", NULL);
    s->outcap = 64 * 1024 * 1024;
    s->outbuf = malloc(s->outcap);
    return s;
}

/* returns 0 on success. ciphertext written to *ct_out (internal buffer, valid until next call), tag 16 bytes to tag_out */
int gcm_encrypt(GcmState *s,
                const unsigned char *key, int klen,
                const unsigned char *nonce, int nlen,
                const unsigned char *pt, int ptlen,
                const unsigned char *aad, int aadlen,
                unsigned char **ct_out, int *ct_len,
                unsigned char *tag_out) {
    if ((size_t)ptlen + 32 > s->outcap) {
        s->outcap = (size_t)ptlen + 64;
        s->outbuf = realloc(s->outbuf, s->outcap);
    }
    EVP_CIPHER_CTX *ctx = s->ctx;
    if (EVP_EncryptInit_ex(ctx, pick(s, klen), NULL, NULL, NULL) != 1) return 1;
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, nlen, NULL) != 1) return 2;
    if (EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce) != 1) return 3;
    int outl = 0;
    if (aad && aadlen > 0) {
        if (EVP_EncryptUpdate(ctx, NULL, &outl, aad, aadlen) != 1) return 4;
    }
    if (EVP_EncryptUpdate(ctx, s->outbuf, &outl, pt, ptlen) != 1) return 5;
    int total = outl;
    if (EVP_EncryptFinal_ex(ctx, s->outbuf + total, &outl) != 1) return 6;
    total += outl;
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag_out) != 1) return 7;
    *ct_out = s->outbuf;
    *ct_len = total;
    /* reset for reuse */
    EVP_CIPHER_CTX_reset(ctx);
    return 0;
}
