#include <openssl/evp.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    EVP_CIPHER *ciphers[3]; /* 16,24,32 -> index (klen/8)-2 */
    unsigned char *buf;
    size_t cap;
} GcmState;

static EVP_CIPHER *pick(GcmState *s, int klen) {
    int idx = (klen / 8) - 2;
    if (idx < 0 || idx > 2) return NULL;
    return s->ciphers[idx];
}

GcmState *gcm_init(void) {
    GcmState *s = calloc(1, sizeof(*s));
    s->ctx = EVP_CIPHER_CTX_new();
    s->ciphers[0] = EVP_CIPHER_fetch(NULL, "AES-128-GCM", NULL);
    s->ciphers[1] = EVP_CIPHER_fetch(NULL, "AES-192-GCM", NULL);
    s->ciphers[2] = EVP_CIPHER_fetch(NULL, "AES-256-GCM", NULL);
    s->cap = (size_t)64 * 1024 * 1024 + 64;
    s->buf = malloc(s->cap);
    return s;
}

/* Encrypt. On success returns pointer to internal buffer of length ptlen (ciphertext) and writes 16-byte tag.
   Buffer valid until next call. */
unsigned char *gcm_encrypt(GcmState *s,
                const unsigned char *key, int klen,
                const unsigned char *nonce, int nlen,
                const unsigned char *pt, int ptlen,
                const unsigned char *aad, int aadlen,
                unsigned char *tag_out) {
    if ((size_t)ptlen + 64 > s->cap) {
        s->cap = (size_t)ptlen + 128;
        unsigned char *nb = realloc(s->buf, s->cap);
        if (!nb) return NULL;
        s->buf = nb;
    }
    EVP_CIPHER_CTX *ctx = s->ctx;
    EVP_CIPHER *cipher = pick(s, klen);
    if (!cipher) return NULL;
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) return NULL;
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, nlen, NULL) != 1) return NULL;
    if (EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce) != 1) return NULL;
    int outl = 0;
    if (aad && aadlen > 0) {
        if (EVP_EncryptUpdate(ctx, NULL, &outl, aad, aadlen) != 1) return NULL;
    }
    if (ptlen > 0) {
        if (EVP_EncryptUpdate(ctx, s->buf, &outl, pt, ptlen) != 1) return NULL;
    } else {
        outl = 0;
    }
    int total = outl;
    if (EVP_EncryptFinal_ex(ctx, s->buf + total, &outl) != 1) return NULL;
    total += outl;
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag_out) != 1) return NULL;
    EVP_CIPHER_CTX_reset(ctx);
    (void)total;
    return s->buf;
}

/* Same but also copies ciphertext into caller-provided out (length ptlen). Returns 0 on success. */
int gcm_encrypt_into(GcmState *s,
                const unsigned char *key, int klen,
                const unsigned char *nonce, int nlen,
                const unsigned char *pt, int ptlen,
                const unsigned char *aad, int aadlen,
                unsigned char *out,
                unsigned char *tag_out) {
    EVP_CIPHER_CTX *ctx = s->ctx;
    EVP_CIPHER *cipher = pick(s, klen);
    if (!cipher) return 1;
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) return 2;
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, nlen, NULL) != 1) return 3;
    if (EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce) != 1) return 4;
    int outl = 0;
    if (aad && aadlen > 0) {
        if (EVP_EncryptUpdate(ctx, NULL, &outl, aad, aadlen) != 1) return 5;
    }
    int total = 0;
    if (ptlen > 0) {
        if (EVP_EncryptUpdate(ctx, out, &outl, pt, ptlen) != 1) return 6;
        total = outl;
    }
    if (EVP_EncryptFinal_ex(ctx, out + total, &outl) != 1) return 7;
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag_out) != 1) return 8;
    EVP_CIPHER_CTX_reset(ctx);
    return 0;
}
EOF
