static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    int N = 60*1024*1024;
    unsigned char *pt = malloc(N);
    unsigned char *ct = malloc(N+32);
    unsigned char key[16], nonce[12], aad[32], tag[16];
    memset(pt, 1, N);
    memset(key, 2, 16);
    memset(nonce, 3, 12);
    memset(aad, 4, 32);
    EVP_CIPHER *cipher = EVP_CIPHER_fetch(NULL, "AES-128-GCM", NULL);
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    int chunks[] = {0, 4096, 16384, 65536, 1<<20, 4<<20, 16<<20, N};
    for (int ci = 0; ci < 8; ci++) {
        int chunk = chunks[ci];
        /* warmup */
        for (int w = 0; w < 1; w++) {
            EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
