                int off=0;
                while (off < N) {
                    int n = chunk;
                    if (off + n > N) n = N - off;
                    EVP_EncryptUpdate(ctx, ct+off, &outl, pt+off, n);
                    off += n;
                }
            }
            EVP_EncryptFinal_ex(ctx, ct, &outl);
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
            EVP_CIPHER_CTX_reset(ctx);
        }
        int reps = 3;
        double t0 = now();
        for (int r = 0; r < reps; r++) {
            EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
            EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
            int outl=0;
            EVP_EncryptUpdate(ctx, NULL, &outl, aad, 32);
            if (chunk == 0 || chunk >= N) {
                EVP_EncryptUpdate(ctx, ct, &outl, pt, N);
            } else {
                int off=0;
                while (off < N) {
                    int n = chunk;
                    if (off + n > N) n = N - off;
                    EVP_EncryptUpdate(ctx, ct+off, &outl, pt+off, n);
                    off += n;
                }
            }
            EVP_EncryptFinal_ex(ctx, ct, &outl);
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
            EVP_CIPHER_CTX_reset(ctx);
        }
        double t1 = now();
        printf("chunk=%8d  per=%.4f s  MB/s=%.0f\n", chunk?chunk:N, (t1-t0)/reps, (N/1e6)/((t1-t0)/reps));
    }
    return 0;
}
