cat > bench_mt.c << 'EOF'
#include <openssl/evp.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

typedef struct {
    unsigned char *pt;
    unsigned char *ct;
    int len;
    unsigned char key[16];
    unsigned char nonce[12];
    EVP_CIPHER *cipher;
    int reps;
} Job;

static void *worker(void *arg) {
    Job *j = arg;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char tag[16];
    unsigned char aad[32] = {0};
    for (int r = 0; r < j->reps; r++) {
        EVP_EncryptInit_ex(ctx, j->cipher, NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, j->key, j->nonce);
        int outl = 0;
        EVP_EncryptUpdate(ctx, NULL, &outl, aad, 32);
        EVP_EncryptUpdate(ctx, j->ct, &outl, j->pt, j->len);
        EVP_EncryptFinal_ex(ctx, j->ct + outl, &outl);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
        EVP_CIPHER_CTX_reset(ctx);
    }
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

/* memory bandwidth: read+write */
static void *membw(void *arg) {
    Job *j = arg;
    for (int r = 0; r < j->reps; r++) {
        /* copy pt -> ct */
        memcpy(j->ct, j->pt, j->len);
        /* touch to prevent optimize */
        j->ct[0] ^= (unsigned char)r;
    }
    return NULL;
}

int main() {
    EVP_CIPHER *cipher = EVP_CIPHER_fetch(NULL, "AES-128-GCM", NULL);
    int N = 60 * 1024 * 1024;
    int threads_list[] = {1, 2, 4, 6, 8, 12};
    for (int ti = 0; ti < 6; ti++) {
        int T = threads_list[ti];
        int chunk = N / T;
        unsigned char *pt = malloc(N);
        unsigned char *ct = malloc(N);
        memset(pt, 1, N);
        pthread_t th[16];
        Job jobs[16];
        int reps = 4;
        /* warmup */
        for (int t = 0; t < T; t++) {
            jobs[t].pt = pt + t * chunk;
            jobs[t].ct = ct + t * chunk;
            jobs[t].len = (t == T-1) ? (N - t*chunk) : chunk;
            memset(jobs[t].key, t+1, 16);
            memset(jobs[t].nonce, t+3, 12);
            jobs[t].cipher = cipher;
            jobs[t].reps = 1;
            pthread_create(&th[t], NULL, worker, &jobs[t]);
        }
        for (int t = 0; t < T; t++) pthread_join(th[t], NULL);

        for (int t = 0; t < T; t++) jobs[t].reps = reps;
        double t0 = now();
        for (int t = 0; t < T; t++) pthread_create(&th[t], NULL, worker, &jobs[t]);
        for (int t = 0; t < T; t++) pthread_join(th[t], NULL);
        double t1 = now();
        double per = (t1 - t0) / reps;
        printf("AESGCM threads=%2d  per=%.4f s  agg MB/s=%.0f\n", T, per, (N/1e6)/per);

        /* memcpy bandwidth */
        for (int t = 0; t < T; t++) jobs[t].reps = reps;
        t0 = now();
        for (int t = 0; t < T; t++) pthread_create(&th[t], NULL, membw, &jobs[t]);
        for (int t = 0; t < T; t++) pthread_join(th[t], NULL);
        t1 = now();
        per = (t1 - t0) / reps;
        printf("MEMCPY threads=%2d  per=%.4f s  copy MB/s=%.0f (read+write %.0f)\n", T, per, (N/1e6)/per, (2.0*N/1e6)/per);
        free(pt); free(ct);
    }
    return 0;
}
EOF
