#include <openssl/evp.h>
#include <openssl/modes.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

/* ---------- parallel CTR via EVP ---------- */
typedef struct {
    unsigned char *pt;
    unsigned char *ct;
    int len;
    unsigned char key[16];
    unsigned char iv[16];
    EVP_CIPHER *cipher;
} CtrJob;

static void *ctr_worker(void *arg) {
    CtrJob *j = arg;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, j->cipher, NULL, NULL, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, j->key, j->iv);
    int outl = 0;
    EVP_EncryptUpdate(ctx, j->ct, &outl, j->pt, j->len);
    EVP_EncryptFinal_ex(ctx, j->ct + outl, &outl);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

static void inc32(unsigned char *b, uint32_t n) {
    /* increment last 32 bits of 16-byte counter by n (big-endian) */
    uint32_t c = ((uint32_t)b[12] << 24) | ((uint32_t)b[13] << 16) | ((uint32_t)b[14] << 8) | b[15];
    c += n;
    b[12] = (c >> 24) & 0xff;
    b[13] = (c >> 16) & 0xff;
    b[14] = (c >> 8) & 0xff;
    b[15] = c & 0xff;
}

/* ---------- GHASH via CRYPTO_gcm128 on zero keystream? 
   We'll compute GHASH by encrypting zeros? No.
   Use a reference AESGCM only for tag check from python later.
   Here just time CTR parallel + a single GHASH via gcm128 encrypt of already-ct? 
   CRYPTO_gcm128_encrypt does both CTR and GHASH.
   We can init gcm, setiv, aad, then... there's no public "ghash only" API.
   We'll time parallel CTR only, and separately time full GCM, to see headroom.
*/

int main() {
    int N = 60 * 1024 * 1024;
    unsigned char *pt = malloc(N);
    unsigned char *ct = malloc(N + 64);
    memset(pt, 0x5a, N);
    unsigned char key[16];
    memset(key, 0x11, 16);
    unsigned char nonce[12];
    memset(nonce, 0x22, 12);

    EVP_CIPHER *ctr = EVP_CIPHER_fetch(NULL, "AES-128-CTR", NULL);
    EVP_CIPHER *gcm = EVP_CIPHER_fetch(NULL, "AES-128-GCM", NULL);

    /* reference GCM */
    unsigned char *ref = malloc(N);
    unsigned char tag[16];
    {
        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, gcm, NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        int outl = 0;
        unsigned char aad[32];
        memset(aad, 0x33, 32);
        EVP_EncryptUpdate(ctx, NULL, &outl, aad, 32);
        EVP_EncryptUpdate(ctx, ref, &outl, pt, N);
        EVP_EncryptFinal_ex(ctx, ref + outl, &outl);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
        EVP_CIPHER_CTX_free(ctx);
    }

    /* J0 for 12-byte nonce = nonce || 0x00000001
       first keystream block is inc32(J0) = nonce || 0x00000002
    */
    int threads_list[] = {1, 2, 4, 6};
    for (int ti = 0; ti < 4; ti++) {
        int T = threads_list[ti];
        /* align chunks to 16 bytes */
        int blocks = N / 16;
        int blocks_per = blocks / T;
        pthread_t th[16];
        CtrJob jobs[16];
        int reps = 4;
        double t0 = now();
        for (int r = 0; r < reps; r++) {
            int off = 0;
            int block_off = 0;
            for (int t = 0; t < T; t++) {
                int nb = (t == T - 1) ? (blocks - block_off) : blocks_per;
                int len = nb * 16;
                /* leftover tail on last thread */
                if (t == T - 1) len = N - off;
                jobs[t].pt = pt + off;
                jobs[t].ct = ct + off;
                jobs[t].len = len;
                memcpy(jobs[t].key, key, 16);
                /* CTR IV = nonce || counter, counter starts at 2 for first block */
                memcpy(jobs[t].iv, nonce, 12);
                jobs[t].iv[12] = 0; jobs[t].iv[13] = 0; jobs[t].iv[14] = 0; jobs[t].iv[15] = 0;
                inc32(jobs[t].iv, (uint32_t)(2 + block_off));
                jobs[t].cipher = ctr;
                pthread_create(&th[t], NULL, ctr_worker, &jobs[t]);
                off += len;
                block_off += nb;
            }
            for (int t = 0; t < T; t++) pthread_join(th[t], NULL);
        }
        double t1 = now();
        int match = memcmp(ct, ref, N) == 0;
        printf("CTR threads=%d per=%.4f MB/s=%.0f match=%d\n", T, (t1-t0)/reps, (N/1e6)/((t1-t0)/reps), match);
    }
    return 0;
}
EOF
cc -O3 -o bench_split bench_split.c -I/usr/local/include -L/usr/local/lib -lcrypto -lpthread 2>&1
