static __m128i reduce(__m128i lo, __m128i hi) {
    __m128i tmp2, tmp3 = lo, tmp4, tmp5, tmp6 = hi, tmp7, tmp8, tmp9;
    tmp7 = _mm_srli_epi32(tmp3, 31);
