    tmp7 = _mm_xor_si128(tmp7, tmp8);
    tmp7 = _mm_xor_si128(tmp7, tmp9);
    tmp8 = _mm_srli_si128(tmp7, 4);
    tmp7 = _mm_slli_si128(tmp7, 12);
    tmp3 = _mm_xor_si128(tmp3, tmp7);
    tmp2 = _mm_srli_epi32(tmp3, 1);
    tmp4 = _mm_srli_epi32(tmp3, 2);
    tmp5 = _mm_srli_epi32(tmp3, 7);
    tmp2 = _mm_xor_si128(tmp2, tmp4);
    tmp2 = _mm_xor_si128(tmp2, tmp5);
    tmp2 = _mm_xor_si128(tmp2, tmp8);
    tmp3 = _mm_xor_si128(tmp3, tmp2);
    tmp6 = _mm_xor_si128(tmp6, tmp3);
    return tmp6;
}

static void ghash4(const unsigned char *H, const unsigned char *data, size_t len, unsigned char out[16]) {
    /* H powers: H^1, H^2, H^3, H^4 in reflected form */
    __m128i h1 = bswap16(_mm_loadu_si128((const __m128i *)H));
    __m128i h2 = gfmul(h1, h1);
    __m128i h3 = gfmul(h2, h1);
    __m128i h4 = gfmul(h2, h2);
    __m128i y = _mm_setzero_si128();
    size_t n = len / 16;
    size_t i = 0;
    size_t n4 = n & ~3ull;
    for (; i < n4; i += 4) {
        __m128i x0 = bswap16(_mm_loadu_si128((const __m128i *)(data + 16*(i+0))));
        __m128i x1 = bswap16(_mm_loadu_si128((const __m128i *)(data + 16*(i+1))));
        __m128i x2 = bswap16(_mm_loadu_si128((const __m128i *)(data + 16*(i+2))));
        __m128i x3 = bswap16(_mm_loadu_si128((const __m128i *)(data + 16*(i+3))));
        /* y = (y ^ x0)*H^4 + x1*H^3 + x2*H^2 + x3*H */
        x0 = _mm_xor_si128(x0, y);
        __m128i hi0, lo0, hi1, lo1, hi2, lo2, hi3, lo3;
        clmul256(x0, h4, &hi0, &lo0);
        clmul256(x1, h3, &hi1, &lo1);
        clmul256(x2, h2, &hi2, &lo2);
        clmul256(x3, h1, &hi3, &lo3);
        __m128i hi = _mm_xor_si128(_mm_xor_si128(hi0, hi1), _mm_xor_si128(hi2, hi3));
        __m128i lo = _mm_xor_si128(_mm_xor_si128(lo0, lo1), _mm_xor_si128(lo2, lo3));
        y = reduce(lo, hi);
    }
    for (; i < n; i++) {
        __m128i x = bswap16(_mm_loadu_si128((const __m128i *)(data + 16*i)));
        y = gfmul(_mm_xor_si128(y, x), h1);
    }
    _mm_storeu_si128((__m128i *)out, bswap16(y));
}

static void ghash1(const unsigned char *H, const unsigned char *data, size_t len, unsigned char out[16]) {
    __m128i h = bswap16(_mm_loadu_si128((const __m128i *)H));
    __m128i y = _mm_setzero_si128();
    size_t n = len / 16;
    for (size_t i = 0; i < n; i++) {
        __m128i x = bswap16(_mm_loadu_si128((const __m128i *)(data + 16*i)));
        y = gfmul(_mm_xor_si128(y, x), h);
    }
    _mm_storeu_si128((__m128i *)out, bswap16(y));
}

int main() {
    int N = 60*1024*1024;
    unsigned char *big = malloc(N+64);
    memset(big, 0xab, N);
    unsigned char H[16];
    for (int i = 0; i < 16; i++) H[i] = i*17+3;
    unsigned char o1[16], o4[16];
    ghash1(H, big, N, o1);
    ghash4(H, big, N, o4);
    printf("match %d\n", memcmp(o1, o4, 16)==0);
    /* odd length blocks */
    ghash1(H, big, 16*5, o1);
    ghash4(H, big, 16*5, o4);
    printf("5 blocks match %d\n", memcmp(o1,o4,16)==0);

    volatile unsigned char sink=0;
    double t0=now();
    for (int i=0;i<5;i++) { ghash4(H, big, N, o4); sink ^= o4[0]; }
    double t1=now();
    printf("ghash4 per=%.4f MB/s=%.0f sink=%u\n", (t1-t0)/5, (N/1e6)/((t1-t0)/5), sink);

    t0=now();
    for (int i=0;i<3;i++) { ghash1(H, big, N, o1); sink ^= o1[0]; }
    t1=now();
    printf("ghash1 per=%.4f MB/s=%.0f sink=%u\n", (t1-t0)/3, (N/1e6)/((t1-t0)/3), sink);
    return 0;
}
