/* Use OpenSSL's gcm_init_clmul + gcm_ghash_clmul if we can match ABI.
   From crypto/modes/gcm128.c historically:
   void gcm_init_clmul(u128 Htable[16], const u64 Xi[2]);
   void gcm_ghash_clmul(u64 Xi[2], const u128 Htable[16], const u8 *inp, size_t len);

   OpenSSL 3 may have changed. Let's try calling and compare.
*/
typedef void (*gcm_init_fn)(void *Htable, const void *H);
typedef void (*gcm_ghash_fn)(void *Xi, const void *Htable, const unsigned char *inp, size_t len);

extern void gcm_init_clmul(void *, const void *);
extern void gcm_ghash_clmul(void *, const void *, const unsigned char *, size_t);
extern void gcm_init_avx(void *, const void *);
extern void gcm_ghash_avx(void *, const void *, const unsigned char *, size_t);

static void ghash4(const unsigned char *H, const unsigned char *data, size_t len, unsigned char out[16]) {
    __m128i h1 = bswap16(_mm_loadu_si128((const __m128i *)H));
    __m128i h2 = gfmul(h1, h1);
    __m128i h3 = gfmul(h2, h1);
    __m128i h4 = gfmul(h2, h2);
    __m128i h5 = gfmul(h4, h1);
    __m128i h6 = gfmul(h4, h2);
    __m128i h7 = gfmul(h4, h3);
    __m128i h8 = gfmul(h4, h4);
    __m128i y = _mm_setzero_si128();
    size_t n = len / 16;
    size_t i = 0;
    size_t n8 = n & ~7ull;
    __m128i powers[8] = {h8, h7, h6, h5, h4, h3, h2, h1};
    for (; i < n8; i += 8) {
        __m128i hi = _mm_setzero_si128();
        __m128i lo = _mm_setzero_si128();
        for (int k = 0; k < 8; k++) {
            __m128i x = bswap16(_mm_loadu_si128((const __m128i *)(data + 16*(i+k))));
            if (k == 0) x = _mm_xor_si128(x, y);
            __m128i thi, tlo;
            clmul256(x, powers[k], &thi, &tlo);
            hi = _mm_xor_si128(hi, thi);
            lo = _mm_xor_si128(lo, tlo);
        }
        y = reduce_std(lo, hi);
    }
    for (; i < n; i++) {
        __m128i x = bswap16(_mm_loadu_si128((const __m128i *)(data + 16*i)));
        y = gfmul(_mm_xor_si128(y, x), h1);
    }
    _mm_storeu_si128((__m128i *)out, bswap16(y));
}

int main() {
    int N = 60*1024*1024;
    unsigned char *big = aligned_alloc(64, N);
    memset(big, 0xab, N);
    unsigned char H[16];
    for (int i = 0; i < 16; i++) H[i] = i*17+3;
    unsigned char o4[16], o8[16], ossl[16];
    ghash4(H, big, N, o4);

    /* try openssl gcm_ghash_clmul. Htable size: historically 16*16=256 bytes, avx maybe more.
       allocate 16*16*4 to be safe. */
    unsigned char Htable[4096];
    memset(Htable, 0, sizeof Htable);
    unsigned char Xi[16] = {0};
    /* H is in big-endian memory form. gcm_init might expect that. */
    gcm_init_clmul(Htable, H);
    gcm_ghash_clmul(Xi, Htable, big, N);
    memcpy(ossl, Xi, 16);
    printf("clmul vs ghash4 match %d\n", memcmp(ossl, o4, 16)==0);
    printf("ossl "); for(int i=0;i<16;i++) printf("%02x", ossl[i]); printf("\n");
    printf("g4   "); for(int i=0;i<16;i++) printf("%02x", o4[i]); printf("\n");

    memset(Xi, 0, 16);
