    gcm_init_avx(Htable, H);
    gcm_ghash_avx(Xi, Htable, big, N);
    printf("avx vs ghash4 match %d\n", memcmp(Xi, o4, 16)==0);
    printf("avx  "); for(int i=0;i<16;i++) printf("%02x", Xi[i]); printf("\n");

    volatile unsigned char sink=0;
    double t0=now();
    for (int i=0;i<4;i++) { ghash4(H, big, N, o8); sink^=o8[0]; }
    double t1=now();
    printf("ghash8 per=%.4f MB/s=%.0f\n", (t1-t0)/4, (N/1e6)/((t1-t0)/4));

    t0=now();
