    unsigned char H[16], X[16], I[16];
    for (int i=0;i<16;i++) H[i]=i*7+1;
    for (int i=0;i<16;i++) X[i]=i*3+9;
    memset(I, 0, 16); I[0]=0x80;
    unsigned char Y[16]; memcpy(Y, X, 16); gcm_mul(Y, I);
    printf("identity msb match %d\n", memcmp(Y, X, 16)==0);
    memset(I, 0, 16); I[15]=1;
    memcpy(Y, X, 16); gcm_mul(Y, I);
    printf("identity lsb match %d\n", memcmp(Y, X, 16)==0);

    int N = 60*1024*1024;
    unsigned char *pt = malloc(N);
    unsigned char *ct = malloc(N);
    unsigned char *ref = malloc(N);
    memset(pt, 0x5a, N);
    unsigned char key[16]; memset(key, 0x11, 16);
    unsigned char nonce[12]; memset(nonce, 0x22, 12);
    unsigned char aad[32]; memset(aad, 0x33, 32);
    unsigned char tag[16], mytag[16];
    ref_gcm(key, 16, nonce, 12, pt, N, aad, 32, ref, tag);

    EVP_CIPHER *ctr = EVP_CIPHER_fetch(NULL, "AES-128-CTR", NULL);
    unsigned char Hraw[16], zero[16]={0};
    aes_ecb_block(key, 16, zero, Hraw);

    unsigned char Htable[4096];
    memset(Htable, 0, sizeof Htable);
    gcm_init_avx(Htable, Hraw);

    int T = 4;
    int blocks = N / 16;
    int bpt = blocks / T;
    pthread_t th[8];
    CtrJob cjobs[8];
    HashJob hjobs[8];

    int reps = 3;
    double t0 = now();
    for (int r = 0; r < reps; r++) {
        int off = 0, boff = 0;
        for (int t = 0; t < T; t++) {
            int nb = (t == T-1) ? (blocks - boff) : bpt;
            int len = (t == T-1) ? (N - off) : nb * 16;
            cjobs[t].pt = pt + off;
            cjobs[t].ct = ct + off;
            cjobs[t].len = len;
            memcpy(cjobs[t].key, key, 16);
            cjobs[t].klen = 16;
            memcpy(cjobs[t].iv, nonce, 12);
            cjobs[t].iv[12]=0; cjobs[t].iv[13]=0; cjobs[t].iv[14]=0; cjobs[t].iv[15]=0;
            inc32(cjobs[t].iv, (uint32_t)(2 + boff));
            cjobs[t].cipher = ctr;
            pthread_create(&th[t], NULL, ctr_worker, &cjobs[t]);
            off += len; boff += nb;
        }
        for (int t = 0; t < T; t++) pthread_join(th[t], NULL);

        /* hash segments */
        off = 0; boff = 0;
        for (int t = 0; t < T; t++) {
            int nb = (t == T-1) ? (blocks - boff) : bpt;
            int len = nb * 16; /* hash only full blocks; tail handled separately */
            if (t == T-1) len = (N - off) & ~15;
            hjobs[t].data = ct + off;
            hjobs[t].len = len;
            hjobs[t].Htable = Htable;
            pthread_create(&th[t], NULL, hash_worker, &hjobs[t]);
            off += (t == T-1) ? (N - off) : len;
            boff += nb;
        }
        for (int t = 0; t < T; t++) pthread_join(th[t], NULL);
    }
    double t1 = now();
    printf("parallel CTR+ghash per=%.4f MB/s=%.0f ct_match=%d\n",
           (t1-t0)/reps, (N/1e6)/((t1-t0)/reps), memcmp(ct, ref, N)==0);

    /* combine hashes: S = X0*H^{n1+n2+n3} + X1*H^{n2+n3} + X2*H^{n3} + X3
       then continue with tail + lengths. For aligned N, no tail.
    */
    int seglen[8];
    int off=0, boff=0;
    for (int t=0;t<T;t++) {
        int nb = (t==T-1)?(blocks-boff):bpt;
        seglen[t]=nb;
        boff += nb;
    }
    /* powers: after segment t there are blocks_after[t] blocks */
    unsigned char acc[16];
    memset(acc, 0, 16);
    uint64_t after = blocks;
    for (int t=0;t<T;t++) {
        after -= seglen[t];
        /* acc = acc + Xi_t * H^{after} */
        unsigned char term[16];
        memcpy(term, hjobs[t].Xi, 16);
        if (after) {
            unsigned char Hp[16];
            gcm_pow(Hraw, after, Hp);
            gcm_mul(term, Hp);
        }
        for (int i=0;i<16;i++) acc[i]^=term[i];
    }
    /* lengths block */
    unsigned char lb[16]={0};
    uint64_t abits=32*8, cbits=(uint64_t)N*8;
    for (int i=0;i<8;i++) lb[i]=(abits>>(56-8*i))&0xff;
    for (int i=0;i<8;i++) lb[8+i]=(cbits>>(56-8*i))&0xff;
    /* also AAD: GHASH starts with AAD. We didn't include AAD!
       For this timing prototype, compare ciphertext only. Tag combine tested separately.
    */
    printf("partial acc ");
    for (int i=0;i<16;i++) printf("%02x", acc[i]);
    printf("\n");

    /* single-thread ghash of whole ct for reference partial */
    unsigned char Xi[16]={0};
    gcm_ghash_avx(Xi, Htable, ct, N);
    bswap16(Xi);
    printf("full Xi    ");
    for (int i=0;i<16;i++) printf("%02x", Xi[i]);
    printf("\ncombine match %d\n", memcmp(acc, Xi, 16)==0);
    return 0;
}
