    __m128i p = _mm_set_epi64x(0xE100000000000000ULL, 0); /* high */
    /* fold */
    __m128i x0 = lo, x1 = hi;
    __m128i a0 = _mm_clmulepi64_si128(x0, _mm_set_epi64x(0, 0xE100000000000000ULL), 0x00);
