         t = clmul(v0, 0xE1<<56)   // only low 64 of v0
         v0 = v0 xor (t << 64)     // i.e. xor high half of t into high of v0? 
         v1 = v1 xor (t >> 64)
         t = clmul(high64(v0), 0xE1<<56)
