typedef struct {
    pthread_t th;
    pthread_mutex_t mu;
    pthread_cond_t cv;
    pthread_cond_t done_cv;
    int has_job;
    int stop;
    int done;
    unsigned char *in, *out;
    int len;
    unsigned char key[32];
    int klen;
    unsigned char iv[16];
    EVP_CIPHER *cipher;
    EVP_CIPHER_CTX *ctx;
} Worker;

static void *worker_fn(void *arg){
    Worker *w=arg;
    pthread_mutex_lock(&w->mu);
    while(1){
        while(!w->has_job && !w->stop) pthread_cond_wait(&w->cv, &w->mu);
        if(w->stop) break;
        pthread_mutex_unlock(&w->mu);
        if(!w->ctx) w->ctx=EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(w->ctx, w->cipher, NULL, NULL, NULL);
        EVP_EncryptInit_ex(w->ctx, NULL, NULL, w->key, w->iv);
        int outl=0;
        EVP_EncryptUpdate(w->ctx, w->out, &outl, w->in, w->len);
        EVP_EncryptFinal_ex(w->ctx, w->out+outl, &outl);
        pthread_mutex_lock(&w->mu);
        w->has_job=0;
        w->done=1;
        pthread_cond_signal(&w->done_cv);
    }
    pthread_mutex_unlock(&w->mu);
    return NULL;
}

static void inc32(unsigned char b[16], uint32_t n){
    uint32_t c=((uint32_t)b[12]<<24)|((uint32_t)b[13]<<16)|((uint32_t)b[14]<<8)|b[15];
