    for (; i < n8; i += 8) {
        __m128i hi = _mm_setzero_si128(), lo = _mm_setzero_si128();
        for (int k = 0; k < 8; k++) {
            __m128i x = bswap16(_mm_loadu_si128((const __m128i *)(data + 16 * (i + k))));
            if (k == 0) x = _mm_xor_si128(x, y);
            __m128i thi, tlo;
            clmul256(x, powers[k], &thi, &tlo);
            hi = _mm_xor_si128(hi, thi);
            lo = _mm_xor_si128(lo, tlo);
        }
        y = reduce_std(lo, hi);
    }
    for (; i < nblocks; i++) {
        __m128i x = bswap16(_mm_loadu_si128((const __m128i *)(data + 16 * i)));
        y = gfmul(_mm_xor_si128(y, x), h1);
    }
    _mm_storeu_si128((__m128i *)out, bswap16(y));
}

static void *worker_fn(void *arg) {
    Worker *w = arg;
    pthread_mutex_lock(&w->mu);
    for (;;) {
        while (!w->has_job && !w->stop) pthread_cond_wait(&w->cv, &w->mu);
        if (w->stop) break;
        const unsigned char *in = w->in;
        unsigned char *out = w->out;
        int len = w->len;
        unsigned char key[32], iv[16];
        int klen = w->klen;
        memcpy(key, w->key, klen);
        memcpy(iv, w->iv, 16);
        EVP_CIPHER *cipher = w->cipher;
        pthread_mutex_unlock(&w->mu);

        if (!w->ctx) w->ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(w->ctx, cipher, NULL, NULL, NULL);
        EVP_EncryptInit_ex(w->ctx, NULL, NULL, key, iv);
        int outl = 0;
        EVP_EncryptUpdate(w->ctx, out, &outl, in, len);
        EVP_EncryptFinal_ex(w->ctx, out + outl, &outl);

        pthread_mutex_lock(&w->mu);
        w->has_job = 0;
        w->done = 1;
        pthread_cond_signal(&w->done_cv);
    }
    pthread_mutex_unlock(&w->mu);
    return NULL;
}

static void inc32(unsigned char b[16], uint32_t n) {
    uint32_t c = ((uint32_t)b[12] << 24) | ((uint32_t)b[13] << 16) | ((uint32_t)b[14] << 8) | b[15];
    c += n;
    b[12] = (unsigned char)(c >> 24);
    b[13] = (unsigned char)(c >> 16);
    b[14] = (unsigned char)(c >> 8);
    b[15] = (unsigned char)c;
}

static void ensure_init(void) {
    if (inited) return;
    ctr_ciphers[0] = EVP_CIPHER_fetch(NULL, "AES-128-CTR", NULL);
    ctr_ciphers[1] = EVP_CIPHER_fetch(NULL, "AES-192-CTR", NULL);
    ctr_ciphers[2] = EVP_CIPHER_fetch(NULL, "AES-256-CTR", NULL);
    ecb_ciphers[0] = EVP_CIPHER_fetch(NULL, "AES-128-ECB", NULL);
    ecb_ciphers[1] = EVP_CIPHER_fetch(NULL, "AES-192-ECB", NULL);
    ecb_ciphers[2] = EVP_CIPHER_fetch(NULL, "AES-256-ECB", NULL);
    gcm_ciphers[0] = EVP_CIPHER_fetch(NULL, "AES-128-GCM", NULL);
    gcm_ciphers[1] = EVP_CIPHER_fetch(NULL, "AES-192-GCM", NULL);
    gcm_ciphers[2] = EVP_CIPHER_fetch(NULL, "AES-256-GCM", NULL);
    ecb_ctx = EVP_CIPHER_CTX_new();
    gcm_ctx = EVP_CIPHER_CTX_new();
    for (int t = 0; t < T; t++) {
        memset(&ws[t], 0, sizeof(ws[t]));
        pthread_mutex_init(&ws[t].mu, NULL);
        pthread_cond_init(&ws[t].cv, NULL);
        pthread_cond_init(&ws[t].done_cv, NULL);
        pthread_create(&ws[t].th, NULL, worker_fn, &ws[t]);
    }
    inited = 1;
}

static void aes_block(const unsigned char *key, int klen, const unsigned char in[16], unsigned char out[16]) {
    int idx = (klen / 8) - 2;
    EVP_EncryptInit_ex(ecb_ctx, ecb_ciphers[idx], NULL, NULL, NULL);
    EVP_EncryptInit_ex(ecb_ctx, NULL, NULL, key, NULL);
    EVP_CIPHER_CTX_set_padding(ecb_ctx, 0);
    int outl = 0;
    EVP_EncryptUpdate(ecb_ctx, out, &outl, in, 16);
    EVP_EncryptFinal_ex(ecb_ctx, out + outl, &outl);
}

static int evp_gcm(const unsigned char *key, int klen,
                   const unsigned char *nonce, int nlen,
                   const unsigned char *pt, int ptlen,
                   const unsigned char *aad, int aadlen,
                   unsigned char *ct, unsigned char *tag) {
    ensure_init();
    int idx = (klen / 8) - 2;
    if (idx < 0 || idx > 2) return -1;
    EVP_CIPHER_CTX_reset(gcm_ctx);
    if (EVP_EncryptInit_ex(gcm_ctx, gcm_ciphers[idx], NULL, NULL, NULL) != 1) return -2;
    if (EVP_CIPHER_CTX_ctrl(gcm_ctx, EVP_CTRL_AEAD_SET_IVLEN, nlen, NULL) != 1) return -3;
    if (EVP_EncryptInit_ex(gcm_ctx, NULL, NULL, key, nonce) != 1) return -4;
    int outl = 0;
    if (aadlen > 0) {
        if (EVP_EncryptUpdate(gcm_ctx, NULL, &outl, aad, aadlen) != 1) return -5;
    }
    if (ptlen > 0) {
        if (EVP_EncryptUpdate(gcm_ctx, ct, &outl, pt, ptlen) != 1) return -6;
    } else {
        outl = 0;
    }
    int total = outl;
    if (EVP_EncryptFinal_ex(gcm_ctx, ct + total, &outl) != 1) return -7;
    if (EVP_CIPHER_CTX_ctrl(gcm_ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag) != 1) return -8;
    return 0;
}

static void parallel_ctr(const unsigned char *key, int klen, const unsigned char *nonce,
                         const unsigned char *pt, int ptlen, unsigned char *ct) {
    int idx = (klen / 8) - 2;
    EVP_CIPHER *cipher = ctr_ciphers[idx];
    int blocks = ptlen / 16;
    int bpt = blocks / T;
    if (ptlen <= 0) return;
    if (bpt == 0) {
        pthread_mutex_lock(&ws[0].mu);
        ws[0].in = pt;
        ws[0].out = ct;
        ws[0].len = ptlen;
        ws[0].klen = klen;
        memcpy(ws[0].key, key, klen);
        memcpy(ws[0].iv, nonce, 12);
        ws[0].iv[12] = ws[0].iv[13] = ws[0].iv[14] = 0;
        ws[0].iv[15] = 2;
        ws[0].cipher = cipher;
        ws[0].done = 0;
        ws[0].has_job = 1;
        pthread_cond_signal(&ws[0].cv);
        pthread_mutex_unlock(&ws[0].mu);
        pthread_mutex_lock(&ws[0].mu);
        while (!ws[0].done) pthread_cond_wait(&ws[0].done_cv, &ws[0].mu);
        pthread_mutex_unlock(&ws[0].mu);
        return;
    }
    int off = 0, boff = 0;
    for (int t = 0; t < T; t++) {
        int nb = (t == T - 1) ? (blocks - boff) : bpt;
        int len = (t == T - 1) ? (ptlen - off) : nb * 16;
        pthread_mutex_lock(&ws[t].mu);
        ws[t].in = pt + off;
        ws[t].out = ct + off;
        ws[t].len = len;
        ws[t].klen = klen;
        memcpy(ws[t].key, key, klen);
        memcpy(ws[t].iv, nonce, 12);
        ws[t].iv[12] = ws[t].iv[13] = ws[t].iv[14] = ws[t].iv[15] = 0;
        inc32(ws[t].iv, (uint32_t)(2 + boff));
        ws[t].cipher = cipher;
        ws[t].done = 0;
        ws[t].has_job = 1;
        pthread_cond_signal(&ws[t].cv);
        pthread_mutex_unlock(&ws[t].mu);
        off += len;
        boff += nb;
    }
    for (int t = 0; t < T; t++) {
        pthread_mutex_lock(&ws[t].mu);
        while (!ws[t].done) pthread_cond_wait(&ws[t].done_cv, &ws[t].mu);
        pthread_mutex_unlock(&ws[t].mu);
    }
}

/* Pad AAD/tail into a small buffer and GHASH it. */
static void ghash_bytes(const unsigned char H[16], const unsigned char *data, size_t len, unsigned char out[16]) {
    size_t full = len & ~15ull;
    size_t rem = len - full;
    unsigned char acc[16];
    ghash_blocks(H, data, full / 16, acc);
    if (rem) {
        unsigned char last[16] = {0};
        memcpy(last, data + full, rem);
        unsigned char gl[16];
        ghash_blocks(H, last, 1, gl);
        __m128i h = bswap16(_mm_loadu_si128((const __m128i *)H));
        __m128i a = bswap16(_mm_loadu_si128((const __m128i *)acc));
        __m128i g = bswap16(_mm_loadu_si128((const __m128i *)gl));
        /* acc * H XOR gl */
        __m128i m = _mm_xor_si128(gfmul(a, h), g);
        _mm_storeu_si128((__m128i *)out, bswap16(m));
    } else {
        memcpy(out, acc, 16);
    }
}

int fast_gcm(const unsigned char *key, int klen,
             const unsigned char *nonce, int nlen,
             const unsigned char *pt, int ptlen,
             const unsigned char *aad, int aadlen,
             unsigned char *ct, unsigned char *tag_out) {
    ensure_init();
    if (klen != 16 && klen != 24 && klen != 32) return -1;
    if (nlen != 12 || ptlen < 256 * 1024) {
        return evp_gcm(key, klen, nonce, nlen, pt, ptlen, aad, aadlen, ct, tag_out);
    }
    parallel_ctr(key, klen, nonce, pt, ptlen, ct);

    unsigned char H[16], zero[16] = {0}, J0[16], EJ0[16];
    aes_block(key, klen, zero, H);
    memcpy(J0, nonce, 12);
    J0[12] = 0;
    J0[13] = 0;
    J0[14] = 0;
    J0[15] = 1;
    aes_block(key, klen, J0, EJ0);

    unsigned char ga[16], gc[16];
    if (aad && aadlen > 0) ghash_bytes(H, aad, (size_t)aadlen, ga);
    else memset(ga, 0, 16);
    ghash_bytes(H, ct, (size_t)ptlen, gc);

    __m128i h = bswap16(_mm_loadu_si128((const __m128i *)H));
    size_t ct_blocks = ((size_t)ptlen + 15) / 16;
    size_t aad_blocks = ((size_t)aadlen + 15) / 16;
    __m128i gas = bswap16(_mm_loadu_si128((const __m128i *)ga));
    __m128i gcs = bswap16(_mm_loadu_si128((const __m128i *)gc));
    __m128i mixed;
    if (aadlen > 0) {
        __m128i hp = gpow(h, ct_blocks);
        mixed = _mm_xor_si128(gfmul(gas, hp), gcs);
    } else {
        mixed = gcs;
    }
    unsigned char lenb[16] = {0};
    uint64_t abits = (uint64_t)aadlen * 8;
    uint64_t cbits = (uint64_t)ptlen * 8;
    for (int i = 0; i < 8; i++) lenb[i] = (unsigned char)(abits >> (56 - 8 * i));
    for (int i = 0; i < 8; i++) lenb[8 + i] = (unsigned char)(cbits >> (56 - 8 * i));
    __m128i lens = bswap16(_mm_loadu_si128((const __m128i *)lenb));
    __m128i S = gfmul(_mm_xor_si128(gfmul(mixed, h), lens), h);
    unsigned char Sb[16];
    _mm_storeu_si128((__m128i *)Sb, bswap16(S));
    for (int i = 0; i < 16; i++) tag_out[i] = Sb[i] ^ EJ0[i];
    (void)aad_blocks;
    return 0;
}
