lib = ctypes.CDLL("./libfastgcm.dylib")
lib.fast_gcm.argtypes = [ctypes.c_void_p,ctypes.c_int,ctypes.c_void_p,ctypes.c_int,ctypes.c_void_p,ctypes.c_int,ctypes.c_void_p,ctypes.c_int,ctypes.c_void_p,ctypes.c_void_p]
lib.fast_gcm.restype = ctypes.c_int
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

def check(klen, nlen, ptlen, aadlen, label):
    key=os.urandom(klen); nonce=os.urandom(nlen); pt=os.urandom(ptlen)
    aad=os.urandom(aadlen) if aadlen else b""
    ct=bytearray(max(ptlen,1)+32); tag=bytearray(16)
    kba=bytearray(key); nba=bytearray(nonce); pba=bytearray(pt) if ptlen else None; aba=bytearray(aad) if aadlen else None
    rc=lib.fast_gcm(
        (c_char*klen).from_buffer(kba), klen,
        (c_char*nlen).from_buffer(nba), nlen,
        (c_char*ptlen).from_buffer(pba) if ptlen else None, ptlen,
        (c_char*aadlen).from_buffer(aba) if aadlen else None, aadlen,
        (c_char*len(ct)).from_buffer(ct),
        (c_char*16).from_buffer(tag))
    ref=AESGCM(key).encrypt(nonce, pt, aad if aadlen else None)
    ok = rc==0 and bytes(ct[:ptlen])+bytes(tag)==ref
    if not ok:
        print(label, "FAIL rc", rc, "tag", bytes(tag).hex(), "reftag", ref[-16:].hex(), "ct", bytes(ct[:ptlen])==ref[:-16])
    else:
        print(label, "ok")
    return ok

ok=True
for args in [
    (16,12,0,0,"empty"),
    (16,12,1,0,"1"),
    (16,12,13,7,"13+7"),
    (16,12,16,0,"16"),
    (16,12,32,32,"32+32"),
    (16,12,100,0,"100"),
    (16,12,100,13,"100+13"),
    (16,12,4096,32,"4k"),
    (16,12,300000,32,"300k"),
    (16,12,300000,0,"300k0"),
    (16,12,300017,13,"300017"),
    (16,12,300016,1,"aligned+1aad"),
    (16,12,1024*1024,32,"1MB"),
    (24,12,300000,32,"192"),
    (32,12,300000,0,"256"),
    (16,16,200,8,"nonce16"),
    (16,12,61440,32,"60k"),
]:
    ok &= check(*args)
print("ALL" if ok else "SOME FAILED")

if ok:
    N=61440000
    key=bytearray(os.urandom(16)); nonce=bytearray(os.urandom(12)); aad=bytearray(os.urandom(32)); pt=bytearray(os.urandom(N))
    ct=bytearray(N); tag=bytearray(16)
    def run():
        return lib.fast_gcm((c_char*16).from_buffer(key),16,(c_char*12).from_buffer(nonce),12,(c_char*N).from_buffer(pt),N,(c_char*32).from_buffer(aad),32,(c_char*N).from_buffer(ct),(c_char*16).from_buffer(tag))
    run()
    ref=AESGCM(bytes(key)).encrypt(bytes(nonce), bytes(pt), bytes(aad))
    print("large match", bytes(ct)+bytes(tag)==ref)
    t0=time.perf_counter()
    for i in range(3):
        run()
    print("large per", (time.perf_counter()-t0)/3)
