    t7=_mm_slli_epi32(t3,31); t8=_mm_slli_epi32(t3,30); t9=_mm_slli_epi32(t3,25);
    t7=_mm_xor_si128(t7,t8); t7=_mm_xor_si128(t7,t9);
    t8=_mm_srli_si128(t7,4); t7=_mm_slli_si128(t7,12); t3=_mm_xor_si128(t3,t7);
    __m128i t2=_mm_srli_epi32(t3,1), t4b=_mm_srli_epi32(t3,2), t5b=_mm_srli_epi32(t3,7);
    t2=_mm_xor_si128(t2,t4b); t2=_mm_xor_si128(t2,t5b); t2=_mm_xor_si128(t2,t8);
    t3=_mm_xor_si128(t3,t2); return _mm_xor_si128(t6,t3);
