    for (int i = 0; i < 8; i++) lb[i] = (unsigned char)(abits >> (56 - 8 * i));
    for (int i = 0; i < 8; i++) lb[8 + i] = (unsigned char)(cbits >> (56 - 8 * i));
    gcm_ghash_avx(Xi, Htable, tail, rem ? 32 : 16);
    /* Xi is byte-reversed GHASH */
    unsigned char S[16];
    for (int i = 0; i < 16; i++) S[i] = Xi[15 - i];

    for (int i = 0; i < 16; i++) tag_out[i] = S[i] ^ EJ0[i];
    return 0;
}
